"use client";

/**
 * Tooltip: a short hint that appears on hover or keyboard focus.
 * Purpose: wraps Radix Tooltip. Generated by shadcn, then re-themed to Grove. Owner: design system.
 * Props: TooltipProvider (once, high in the tree), Tooltip, TooltipTrigger, TooltipContent (side, sideOffset).
 * Responsive: touch screens have no hover, so never put essential information in a tooltip.
 * Accessibility: reachable by keyboard focus; Escape closes it. The trigger keeps its own accessible name.
 * States: closed, open. Dependencies: radix Tooltip, cn. Tests: controls.test.tsx; Design Lab "Feedback" (S2-T07).
 * UX reference: ds-feedback, tooltip (c-core.css .tip).
 */
import { Tooltip as TooltipPrimitive } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

function TooltipProvider({
  delayDuration = 300,
  ...props
}: ComponentProps<typeof TooltipPrimitive.Provider>) {
  return (
    <TooltipPrimitive.Provider
      data-slot="tooltip-provider"
      delayDuration={delayDuration}
      {...props}
    />
  );
}

function Tooltip(props: ComponentProps<typeof TooltipPrimitive.Root>) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
}

function TooltipTrigger(props: ComponentProps<typeof TooltipPrimitive.Trigger>) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />;
}

function TooltipContent({
  className,
  sideOffset = 6,
  children,
  ...props
}: ComponentProps<typeof TooltipPrimitive.Content>) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        data-slot="tooltip-content"
        sideOffset={sideOffset}
        className={cn(
          "z-menu w-fit max-w-64 rounded-sm bg-ink px-3 py-2 text-caption font-medium text-balance text-on-primary shadow-pop",
          className,
        )}
        {...props}
      >
        {children}
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };
